svg.script:
//Load the iframe by grabbing the URL
document.addEventListener('DOMContentLoaded', function() {
  console.log("DOMContentLoaded")
  var iframe = parent.document.getElementById('ltiContentFrame');
  var anchors = parent.document.querySelectorAll('a');
  console.log("Getting inworld content URL for iframe.")
  // Iterate over each anchor tag
  anchors.forEach((anchor) => {
    console.log(anchor)
    if (anchor.href.startsWith("https://arcade.inworld.ai")) {
      //console.log('Found href starting with "cloud.scorm.com":', anchor.href);
      console.log('Found href starting with "https://arcade.inworld.ai":', anchor.href);
      iframe.src = anchor.href
      parent.monitorIframe();
    }
  });
});
